//! RULE: the experiment report an ENDED experiment owes is generated by whichever
//! operation materialises that end.
//!
//! An experiment started from a template that configured an `experimentReportConfiguration`
//! owes the clock TWO writes once its run ends: the terminal status, and the report written
//! to the Amazon S3 output the configuration names. Both fall due at the SAME event — the
//! end of the run — so an operation that settles an experiment and thereby ends its run
//! performs both, whichever operation that happens to be. A client therefore never has to
//! call one particular operation for the report of an ended experiment to exist, and two
//! callers at one instant cannot disagree about whether it does.
//!
//! The rows differ along the operation that OBSERVES the end — the only FIS call the client
//! makes while the run elapses — and along the form of the configured output prefix:
//!
//! * `ListExperiments`, the natural poll for "are my experiments done?", which settles every
//!   experiment;
//! * `StopExperiment`, which settles the experiment before refusing a stop that arrived
//!   after its run had already ended;
//! * `StartExperiment`, replaying the token of ANOTHER experiment, which settles every
//!   experiment so the account's active-experiment quota is taken against the runs genuinely
//!   under way;
//! * `UpdateSafetyLeverState` engaging the lever, whose sweep over the running experiments
//!   settles every one of them.
//!
//! Each row polls ONLY its own observer (and Amazon S3, to see whether the object is there),
//! so the report it finds can only have been written by that operation: no row ever reads
//! the experiment until the object has appeared.
//!
//! The harness this suite needs is shared rather than copied: the sibling
//! [`crate::safety_lever_settles_and_reports`] suite, which takes `UpdateSafetyLeverState`'s
//! store-wide sweep on its own, drives the same lever request, report configuration and
//! post-read generation assertions from here.

use std::time::Duration;

use serde_json::{json, Value};
use smithy_server_runtime::MultiServiceRouter;

use crate::experiment_lifecycle::{
    get_experiment, send, start_experiment, stop_experiment, token, Answer, FALLBACK_REGION,
};
use crate::experiment_state_reason_and_report::{
    emulator_with_object_storage, given_report_bucket, s3, start_from, template_for, Ending, BUCKET,
};

/// The id of the account's one safety lever, which FIS names by a fixed id.
pub(crate) const LEVER_ID: &str = "default";

/// How long a row may take to have its report written: the compressed run window plus the
/// transitions around it and slack for a loaded machine.
const REPORT_BUDGET: Duration = Duration::from_secs(25);

/// How often a row calls its observer while it waits.
const INTERVAL: Duration = Duration::from_millis(100);

/// The one FIS operation a row calls while its run elapses — the operation that ends up
/// materialising the end of that run.
#[derive(Debug, Clone, Copy)]
enum Observer {
    ListExperiments,
    StopExperiment,
    StartAnotherExperiment,
    EngageSafetyLever,
}

/// One row: where its report goes, which operation observes the end, and the status its run
/// ends in under that observer.
struct Row {
    case: &'static str,
    /// The `prefix` the configured output names, or `None` for an output that names none.
    prefix: Option<&'static str>,
    /// The key the report object must be written under, with `{id}` standing for the
    /// experiment id. Spelled out per row rather than computed by the crate.
    key: &'static str,
    observer: Observer,
    /// The terminal `state.status` the run reaches under this row's observer: an observer
    /// that only reports leaves the run to elapse, while the stop and the lever end it.
    terminal: &'static str,
}

fn rows() -> Vec<Row> {
    vec![
        Row {
            case: "polled-only-through-list-experiments",
            prefix: Some("list"),
            key: "list/{id}/experiment-report.json",
            observer: Observer::ListExperiments,
            terminal: "completed",
        },
        Row {
            case: "stop-that-arrives-after-the-run-ended",
            prefix: Some("stop/"),
            key: "stop/{id}/experiment-report.json",
            observer: Observer::StopExperiment,
            terminal: "stopped",
        },
        Row {
            case: "start-replaying-another-experiments-token",
            prefix: None,
            key: "{id}/experiment-report.json",
            observer: Observer::StartAnotherExperiment,
            terminal: "completed",
        },
        Row {
            case: "safety-lever-engaged",
            prefix: Some("lever/2026"),
            key: "lever/2026/{id}/experiment-report.json",
            observer: Observer::EngageSafetyLever,
            terminal: "stopped",
        },
    ]
}

/// The `experimentReportConfiguration` a row's template carries.
pub(crate) fn report_configuration(prefix: Option<&str>, bucket: &str) -> Value {
    let mut s3_configuration = json!({ "bucketName": bucket });
    if let Some(prefix) = prefix {
        s3_configuration["prefix"] = json!(prefix);
    }
    json!({ "outputs": { "s3Configuration": s3_configuration } })
}

/// Engage the account's one safety lever once, under `reason`.
pub(crate) async fn engage_lever(router: &MultiServiceRouter, reason: &str) -> Answer {
    send(
        router,
        "PATCH",
        &format!("/safetyLevers/{LEVER_ID}/state"),
        Some(json!({ "state": { "status": "engaged", "reason": reason } })),
        FALLBACK_REGION,
    )
    .await
}

/// The lever answered, and reports `expected`: the transient `engaging` while the engage is
/// still taking effect, and `engaged` once the clock says it has.
pub(crate) fn assert_engaged(case: &str, answer: &Answer, expected: &str) {
    assert_eq!(
        answer.status, 200,
        "case {case:?}: expected the lever to be engaged, got {} with {:?}",
        answer.status, answer.body
    );
    let state = answer.member("safetyLever")["state"].clone();
    assert_eq!(
        state["status"].as_str().unwrap_or_default(),
        expected,
        "case {case:?}: expected the engaged lever to report {expected:?}, got {state:?}"
    );
}

/// The report object at `key`, or `None` when the bucket holds no such object.
///
/// Absence is the modelled absence and nothing else: a status that is neither the object nor
/// `NoSuchKey` (404) panics here, so a case asserting that no report was written cannot pass
/// on a call that merely failed.
pub(crate) async fn report_object(
    router: &MultiServiceRouter,
    case: &str,
    key: &str,
) -> Option<Value> {
    let (status, body) = s3(router, "GET", &format!("/{BUCKET}/{key}")).await;
    if status != 200 {
        assert_eq!(
            status,
            404,
            "case {case:?}: reading s3://{BUCKET}/{key} must answer the object or report that \
             there is none, got {status} with {:?}",
            String::from_utf8_lossy(&body)
        );
        return None;
    }
    Some(
        serde_json::from_slice::<Value>(&body).unwrap_or_else(|error| {
            panic!(
                "case {case:?}: the report at s3://{BUCKET}/{key} is not JSON ({error}): {:?}",
                String::from_utf8_lossy(&body)
            )
        }),
    )
}

/// Assert that `report` is the generation the end of a run made due, as the experiment itself
/// reports it: completed, with no error, naming exactly the one object at `key` that was
/// written.
pub(crate) fn assert_generation_names_object(case: &str, report: &Value, key: &str) {
    assert_eq!(
        report["state"]["status"].as_str().unwrap_or_default(),
        "completed",
        "case {case:?}: expected the generation to be completed, got {report:?}"
    );
    assert!(
        report["state"]["error"].is_null(),
        "case {case:?}: a generated report reports no error, got {report:?}"
    );
    let s3_reports = report["s3Reports"]
        .as_array()
        .unwrap_or_else(|| panic!("case {case:?}: no s3Reports in {report:?}"))
        .clone();
    assert_eq!(
        s3_reports.len(),
        1,
        "case {case:?}: expected the one object that was written to be named, got {s3_reports:?}"
    );
    assert_eq!(
        s3_reports[0]["arn"].as_str().unwrap_or_default(),
        format!("arn:aws:s3:::{BUCKET}/{key}"),
        "case {case:?}: expected the report arn to name the object that was written, got \
         {s3_reports:?}"
    );
}

/// Make this row's observing call once. Its answer is deliberately unused: the row asserts
/// what the call MATERIALISED, not what it reported, and a stop that arrives after the run
/// ended is refused while still having settled the experiment.
async fn observe(router: &MultiServiceRouter, row: &Row, id: &str, replayed_start: &Value) {
    match row.observer {
        Observer::ListExperiments => {
            send(router, "GET", "/experiments", None, FALLBACK_REGION).await;
        }
        Observer::StopExperiment => {
            stop_experiment(router, id).await;
        }
        Observer::StartAnotherExperiment => {
            start_experiment(router, replayed_start.clone()).await;
        }
        Observer::EngageSafetyLever => {
            engage_lever(router, "report follows the end").await;
        }
    }
}

/// RULE: whichever operation materialises the end of a run writes the report that end makes
/// due, to the output the experiment's configuration names.
#[tokio::test]
async fn the_operation_that_ends_a_run_writes_the_report_that_end_makes_due() {
    for row in rows() {
        // One emulator per row: the rows differ in which single operation the client calls,
        // so a row must not see a call another row made.
        let router = emulator_with_object_storage();
        given_report_bucket(&router).await;

        let template_id = template_for(
            &router,
            row.case,
            Ending::Elapses,
            json!({
                "experimentReportConfiguration": report_configuration(row.prefix, BUCKET)
            }),
        )
        .await;
        let started = start_from(&router, row.case, &template_id).await;
        let experiment = started.member("experiment").clone();
        let id = experiment["id"]
            .as_str()
            .unwrap_or_else(|| panic!("case {:?}: no experiment id in {experiment:?}", row.case))
            .to_string();
        assert_eq!(
            experiment["experimentReport"]["state"]["status"]
                .as_str()
                .unwrap_or_default(),
            "pending",
            "case {:?}: a report is pending until its experiment ends, got {experiment:?}",
            row.case
        );

        // The second experiment the start-observing row replays the token of: it configures
        // no report of its own, so the only report this row can find is the first
        // experiment's.
        let replayed_start = if matches!(row.observer, Observer::StartAnotherExperiment) {
            let other_template = template_for(
                &router,
                &format!("{}-other", row.case),
                Ending::Elapses,
                json!({}),
            )
            .await;
            let body = json!({
                "clientToken": token(&format!("report-follows-{}-other", row.case)),
                "experimentTemplateId": other_template
            });
            let other = start_experiment(&router, body.clone()).await;
            assert_eq!(
                other.status, 200,
                "case {:?}: expected the second experiment to start, got {} with {:?}",
                row.case, other.status, other.body
            );
            body
        } else {
            Value::Null
        };

        let key = row.key.replace("{id}", &id);
        // Nothing is written while the run is still going.
        let (status, _) = s3(&router, "GET", &format!("/{BUCKET}/{key}")).await;
        assert_ne!(
            status, 200,
            "case {:?}: expected no report at s3://{BUCKET}/{key} before the run ended",
            row.case
        );

        // Only this row's observer is called from here until the report object exists:
        // nothing else can have written it.
        let deadline = std::time::Instant::now() + REPORT_BUDGET;
        let document = loop {
            observe(&router, &row, &id, &replayed_start).await;
            let (status, body) = s3(&router, "GET", &format!("/{BUCKET}/{key}")).await;
            if status == 200 {
                break serde_json::from_slice::<Value>(&body).unwrap_or_else(|error| {
                    panic!(
                        "case {:?}: the report object is not JSON ({error}): {:?}",
                        row.case,
                        String::from_utf8_lossy(&body)
                    )
                });
            }
            assert!(
                std::time::Instant::now() < deadline,
                "case {:?}: expected {:?} to write the report of the ended experiment \
                 {id} to s3://{BUCKET}/{key} within {REPORT_BUDGET:?}, got {status} with {:?}",
                row.case,
                row.observer,
                String::from_utf8_lossy(&body)
            );
            tokio::time::sleep(INTERVAL).await;
        };

        // The report is about THIS experiment and states the status its run ended in.
        assert_eq!(
            document["experiment"]["id"].as_str().unwrap_or_default(),
            id.as_str(),
            "case {:?}: expected the report to be about {id}, got {document:?}",
            row.case
        );
        assert_eq!(
            document["experiment"]["state"]["status"]
                .as_str()
                .unwrap_or_default(),
            row.terminal,
            "case {:?}: expected the report to state the status the run ended in, got {:?}",
            row.case,
            document["experiment"]["state"]
        );

        // And the experiment itself now reports the generation that happened, with the
        // object it was written to named — the same report state the row's observer already
        // materialised, so this read changes nothing.
        let read = get_experiment(&router, &id).await.member("experiment").clone();
        assert_eq!(
            read["state"]["status"].as_str().unwrap_or_default(),
            row.terminal,
            "case {:?}: expected the run to end {}, got {read:?}",
            row.case,
            row.terminal
        );
        assert_generation_names_object(row.case, &read["experimentReport"], &key);
    }
}

/// RULE, from the other side: an experiment whose run has ended reports the SAME report
/// state to every operation that reports it, so a client that polls `ListExperiments` and a
/// client that reads the experiment never disagree about whether the report exists.
///
/// The row above proves the object is written on the listing path; this one proves the
/// listing path leaves nothing for a later read to write — the generation a read finds is
/// the one the listing already performed, naming the one object that was written.
#[tokio::test]
async fn a_read_after_a_listing_finds_the_generation_the_listing_performed() {
    let router = emulator_with_object_storage();
    given_report_bucket(&router).await;

    let case = "listing-then-reading";
    let template_id = template_for(
        &router,
        case,
        Ending::Elapses,
        json!({
            "experimentReportConfiguration": report_configuration(Some("agreement"), BUCKET)
        }),
    )
    .await;
    let id = start_from(&router, case, &template_id)
        .await
        .member("experiment")["id"]
        .as_str()
        .expect("a started experiment names its id")
        .to_string();

    // Polled only through the listing, as the client that asks "are my experiments done?"
    // does, and then read exactly once.
    let deadline = std::time::Instant::now() + REPORT_BUDGET;
    loop {
        let listed = send(&router, "GET", "/experiments", None, FALLBACK_REGION).await;
        let summary = listed
            .member("experiments")
            .as_array()
            .unwrap_or_else(|| panic!("case {case:?}: no experiments in {:?}", listed.body))
            .iter()
            .find(|summary| summary["id"].as_str() == Some(id.as_str()))
            .unwrap_or_else(|| panic!("case {case:?}: {id} is not listed in {:?}", listed.body))
            .clone();
        if summary["state"]["status"].as_str() == Some("completed") {
            break;
        }
        assert!(
            std::time::Instant::now() < deadline,
            "case {case:?}: expected the listed run to end within {REPORT_BUDGET:?}, \
             got {summary:?}"
        );
        tokio::time::sleep(INTERVAL).await;
    }

    let key = format!("agreement/{id}/experiment-report.json");
    // The listing has ALREADY generated the report: the object is there before anybody
    // reads the experiment, so the read below cannot be what wrote it.
    let (status, body) = s3(&router, "GET", &format!("/{BUCKET}/{key}")).await;
    assert_eq!(
        status,
        200,
        "case {case:?}: expected the report object at s3://{BUCKET}/{key} once the listing \
         reported the run as ended, got {status} with {:?}",
        String::from_utf8_lossy(&body)
    );

    let report = get_experiment(&router, &id).await.member("experiment")["experimentReport"].clone();
    assert_generation_names_object(case, &report, &key);
}

